#!/bin/sh
# The repo's deterministic checks. factory/bin/gate runs the main checkout's copy of
# this file inside a job's worktree; exit 0 means the gate passes.
# Generated by Eminzo from the files found in the repo: review it.
#
# Node: the repo's own package.json scripts (lint and typecheck only when they exist, then test).
# FACTORY_CHECK_MODE is "focused" while a builder iterates and "full" for the gate and the merge;
# in focused mode FACTORY_CHANGED_FILES names a file that lists the changed paths, one repo-relative
# path per line. Narrowing is a shortcut: an empty selection runs everything, and the full run
# below is the backstop. The generator keeps the narrowing block only when the test script is plain
# `jest` (a script with flags or config, or another runner, always runs in full).
set -e
MODE="${FACTORY_CHECK_MODE:-full}"
CHANGED="${FACTORY_CHANGED_FILES:-}"
# Read once, then unset, so a test that starts another factory process does not inherit them.
unset FACTORY_CHECK_MODE FACTORY_CHANGED_FILES

@STATIC@
# focused:begin
if [ "$MODE" = focused ] && [ -n "$CHANGED" ] && [ -s "$CHANGED" ]; then
  # The changed source files that still exist (./ keeps a name starting with - from being an option).
  sel=$(while IFS= read -r f; do [ -e "$f" ] && printf '%s\n' "./$f"; done < "$CHANGED" | grep -E '\.(js|jsx|ts|tsx|mjs|cjs)$' || true)
  if [ -n "$sel" ]; then
    # Run only if jest finds tests related to them; no related test falls through to the full run.
    related=$(printf '%s\n' "$sel" | tr '\n' '\0' | xargs -0 npx --no-install jest --listTests --findRelatedTests || true)
    if [ -n "$related" ]; then printf '%s\n' "$sel" | tr '\n' '\0' | xargs -0 npx --no-install jest --findRelatedTests; exit $?; fi
  fi
fi
# focused:end

@TEST@
